import{_ as l,o,c as r,a2 as a}from"./chunks/framework.BV21bweQ.js";const q=JSON.parse('{"title":"地脉与魔法","description":"","frontmatter":{},"headers":[],"relativePath":"中层/世界/地脉与魔法.md","filePath":"中层/世界/地脉与魔法.md","lastUpdated":1787066340000}'),n={name:"中层/世界/地脉与魔法.md"};function s(e,t,i,g,u,d){return o(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="地脉与魔法" tabindex="-1">地脉与魔法 <a class="header-anchor" href="#地脉与魔法" aria-label="Permalink to &quot;地脉与魔法&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>地脉与魔法是神造物世界观中的核心中层设定。地脉是&quot;大地的伤口&quot;——字面意义上地球曾遭受的行星级破坏（前传事件）留下的贯穿伤；魔法则源自变化神权的神力溢散。两者共同构成了福瑞世界魔法体系的基础，也是共同体崩溃、黑暗时代开启的关键背景。</p><h2 id="地脉" tabindex="-1">地脉 <a class="header-anchor" href="#地脉" aria-label="Permalink to &quot;地脉&quot;">​</a></h2><h3 id="表象与观测特征" tabindex="-1">表象与观测特征 <a class="header-anchor" href="#表象与观测特征" aria-label="Permalink to &quot;表象与观测特征&quot;">​</a></h3><p>地脉表现为从地面上呈线性冒出的白色光芒，其亮度从微弱到明亮不等。</p><p><strong>观测特征：</strong></p><ul><li><strong>连接性</strong>：追踪观察表明，所有地脉最终都相互连接，构成一个连续的网络结构</li><li><strong>再生性</strong>：曾有尝试挖掘地脉的行为，但地脉会在新的地表位置重新显现光芒，即使将泥土回填，地脉也会在一段时间后再次出现在地表之上</li><li><strong>神明的警示</strong>：当被问及地脉本质时，神明曾如此警示：&quot;尽量远离地脉，不要在地脉上修建东西，那是大地的伤口，而且并没有愈合。&quot;</li></ul><h3 id="地脉的终极源头" tabindex="-1">地脉的终极源头 <a class="header-anchor" href="#地脉的终极源头" aria-label="Permalink to &quot;地脉的终极源头&quot;">​</a></h3><ul><li><strong>前传BOSS的飞升与地球撕裂</strong>：地脉的终极源头是<strong>前传BOSS飞升基底层时，撕裂地球薄弱点所形成的伤口</strong>。BOSS察觉现实世界并非&quot;最真实的世界&quot;后，渴望进一步飞升进入基底层，试图为虚拟人类寻找更&quot;真实&quot;的生存空间；地球是现实宇宙与基底层连接的薄弱点，BOSS为打破这一薄弱点、打开通往基底层的通道，选择炸毁地球，却因对基底层的无知产生巨大后坐力，直接撕裂了地球，成为地脉形成的终极根源。</li><li><strong>贯穿伤模型</strong>：地球存在一条<strong>贯穿伤（北美—喜马拉雅）</strong>——前传决战中能量炮偏移虽被击偏，仍贯穿地球，摧毁了北美洲与大半喜马拉雅。基于这条贯穿伤延伸出地脉裂隙；主线福瑞大陆上的地脉<strong>大多由喜马拉雅一端延伸而来</strong>。</li><li><strong>精灵的镇压维护</strong>：在地脉灾难之前，喜马拉雅的世界树尚未被摧毁，地脉源头一直被精灵们借由世界树<strong>镇压维护</strong>，故地脉始终处于相对平稳的状态。地脉灾难后世界树断裂、精灵失去镇压之力，地脉才开始愈发明显地蔓延，缓慢地撕裂福瑞们生活的大陆。</li><li><strong>BOSS计划的未竟之果</strong>：前传中BOSS虽被消灭，但其计划并未完全失败，其打造的装置成功启动，将<strong>虚拟人类送入了基底层</strong>，成为后续地脉危机的核心诱因。</li><li><strong>基底层人类的扭曲</strong>：基底层的无时间、非线性时空特性，让进入其中的虚拟人类逐渐被<strong>扭曲同化</strong>，失去原本的人类形态，成为诡异的高维生物，但他们&quot;返回现实宇宙&quot;的执念不仅未消失，反而愈发强烈。</li></ul><blockquote><p><strong>详细内容参见</strong>：<a href="./../历史/前传超算纪元">前传超算纪元</a></p></blockquote><h3 id="地脉危机的本质" tabindex="-1">地脉危机的本质 <a class="header-anchor" href="#地脉危机的本质" aria-label="Permalink to &quot;地脉危机的本质&quot;">​</a></h3><p>共同体时期的<strong>第一次地脉危机</strong>——即大陆生灵所记录的那次地脉危机——并非自然灾难或神权溢散，而是<strong>基底层的扭曲人类试图通过地球被撕裂的薄弱点，强行突破回现实宇宙</strong>。他们的高维力量冲击现实，导致地脉光芒增强、地表隆起、能量暴走，形成了地脉危机。北美与喜马拉雅作为地脉源头，自然承受最大的冲击，但二者并非冲击目标。</p><ul><li><strong>甲族的拦截</strong>：甲族拼尽全力拦截的，并非地脉本身，而是扭曲人类的突破力量</li><li><strong>维斯塔的宏愿</strong>：维斯塔在此次危机中被地脉吞没，最终许下宏愿，本质是<strong>用神权压制基底层扭曲人类的突破，试图缝合地球被撕裂的薄弱点</strong>；也正因这份宏愿，维斯塔陷入&quot;死亡清算&quot;的悖论状态，与拉斯塔形成变化神权的双载体</li></ul><blockquote><p><strong>详细内容参见</strong>：<a href="./../../底层/规则/基底层与现实世界" class="layer-link" data-layer="底层">基底层与现实世界</a></p></blockquote><h3 id="建国171年地脉灾难" tabindex="-1">建国171年地脉灾难 <a class="header-anchor" href="#建国171年地脉灾难" aria-label="Permalink to &quot;建国171年地脉灾难&quot;">​</a></h3><p><strong>前兆（建国171年开始）：</strong></p><ul><li>光芒亮度明显增加，逐渐有了宽度</li><li>地表出现几毫米到数厘米不定的高低差</li></ul><p><strong>神明失踪：</strong></p><ul><li>空中再次降下金色光柱，带神明去了不知什么地方</li><li>不到一个下午的时间便返回，但面色凝重</li></ul><p><strong>甲族动员（建国171年年末）：</strong></p><ul><li>神明召集甲族将领，告知灾难即将降临，需要他们作为最后的防线</li><li>甲族团结一致，无畏牺牲</li></ul><p><strong>鹤族的执政困境：</strong></p><ul><li>在地脉灾难爆发前，神明因长期处理地脉问题，已将部分管理权力移交鹤族。然而，负责政治事务的鹤族陷入困境：</li><li><strong>威信不足</strong>：虽有理论知识，但缺乏顶层实践经验。民众普遍抱怨&quot;鹤族的管理远不如神明&quot;</li><li><strong>决策瘫痪</strong>：高层决策因无法服众而陷入停滞，只能等待神明回归处理，导致社会问题逐渐积压，为后续共同体崩溃埋下伏笔</li></ul><p><strong>最终爆发：</strong></p><ul><li>地脉毫无征兆地爆发涌动，主要力量直奔神明</li><li>甲族拼尽全力拦截余波，但未能完全阻挡</li><li>神明本体被地脉吞没，暂时失去意识，漂浮于神殿中央</li></ul><h3 id="神明的退场-q7-新设定版" tabindex="-1">神明的退场（Q7 新设定版） <a class="header-anchor" href="#神明的退场-q7-新设定版" aria-label="Permalink to &quot;神明的退场（Q7 新设定版）&quot;">​</a></h3><ol><li><strong>许下宏愿</strong>：第三代变化神（红星/维斯塔）许下修复地脉的宏愿，欲以变化神权修补贯穿伤、压制基底层扭曲人类的突破。</li><li><strong>神机立新规</strong>：神机立即使用上位创造神权，创造&quot;<strong>下位神权无法修改编辑基底层</strong>&quot;这一新规则。维斯塔的宏愿许下时成功，生效时却因新规则而无法达成目标，&quot;卡上BUG&quot;进入悖论状态。</li><li><strong>地脉围困</strong>：宏愿生效的庞大变化权柄附着于每一道地脉——无法压回修复，却将地脉彻底围住，使其生长大大减缓甚至静止，并在现实排斥基底层的规则下逐渐收缩。这些附着变化权柄的地脉成为&quot;魔力&quot;的来源。</li><li><strong>昏迷与断联</strong>：宏愿力量/信息冲击令维斯塔大脑宕机。起初连接着神殿，本可缓慢恢复；但鹿族心急发起&quot;复活神明计划&quot;，令神殿与神明彻底断联。</li><li><strong>神权继承触发</strong>：宏愿代价触发神权继承流程，拉斯塔作为下一代载体被触发并卡在新生阶段，形成&quot;自身卡死亡 + 拉斯塔卡新生&quot;的双载体悖论。</li><li><strong>迟来的唤醒</strong>：约黑暗时代百年，在神机指示下的狐族少女将破败神殿与神明重新连接（外接算力远强于维斯塔自身），才勉强唤醒维斯塔；此时地脉已大肆扩展，维斯塔遂暂留神殿压制地脉。</li></ol><blockquote><p><strong>详细内容参见</strong>：<a href="./../../底层/规则/神权体系" class="layer-link" data-layer="底层">神权体系</a>、<a href="./../人物/维斯塔">维斯塔</a></p></blockquote><h2 id="魔法" tabindex="-1">魔法 <a class="header-anchor" href="#魔法" aria-label="Permalink to &quot;魔法&quot;">​</a></h2><h3 id="魔法来源真相" tabindex="-1">魔法来源真相 <a class="header-anchor" href="#魔法来源真相" aria-label="Permalink to &quot;魔法来源真相&quot;">​</a></h3><p>地脉灾难后，某种源自于地脉的波动逐渐带来了一种奇特的力量，其可以使特殊人群用意志操控现实，某种程度宛如微缩版的神明。这种力量被按照传说故事里的名称，粗略地命名为&quot;魔法&quot;。</p><ul><li><strong>来源</strong>：魔法来源于<strong>变化神权的神力溢散</strong>——维斯塔宏愿生效后，庞大变化权柄附着于每一道地脉之上，成为魔力来源的本体；其小部分会从地脉上逸散到那些充满变化的地方（大部分情况下就是生物）</li><li><strong>附着区域</strong>：从伤口溢散出来的神力会无意识地附着在<strong>变化较为显著的区域</strong>，如生物大脑等部位</li><li><strong>觉醒时期</strong>：魔法天赋的觉醒一般发生在四岁后、八岁前</li></ul><h3 id="法师疾病" tabindex="-1">法师疾病 <a class="header-anchor" href="#法师疾病" aria-label="Permalink to &quot;法师疾病&quot;">​</a></h3><p>魔法会导致法师罹患特殊疾病：</p><ul><li><strong>症状</strong>：欲望变强，情绪不稳，思维能力受到影响，体内激素紊乱，同时丧失种族原本的强大自愈能力与身体素质</li><li><strong>强度关系</strong>：法师魔法力量越强，疾病越严重，死亡速度越快</li><li><strong>唯一缓解手段</strong>：唯有食用智慧种族的新鲜血肉方能缓解痛苦，这直接导致了贯穿黑暗时代的&quot;法师食人史&quot;（食人一事为法师阶层的最高秘密，一般也只有较为强大的法师才需要进行食人，普通人与弱小法师均不知情）</li></ul><p><strong>深层机制：</strong></p><ul><li><strong>食人缓解原理</strong>：摄入智慧种族新鲜血肉会产生**&quot;变化中和效应&quot;**——暂时稳定身体的变化状态、减少神力附着，从而缓解症状；因需持续摄入以维持稳定，形成恶性循环</li><li><strong>因果关系相反</strong>：<strong>并非魔法导致疾病，而是疾病发生使魔法力量增强</strong>。因为身体在崩溃、腐化过程中产生更多变化，故而法力随之增强</li></ul><h3 id="法力周期性波动" tabindex="-1">法力周期性波动 <a class="header-anchor" href="#法力周期性波动" aria-label="Permalink to &quot;法力周期性波动&quot;">​</a></h3><p>法力会随太阳起落与潮汐变化产生周期性波动。太阳作为巨大的反应炉，法力倾向于向太阳方向移动，因此白天法力向上流动，夜晚则向下沉降。</p><h3 id="黑暗时代中的魔法" tabindex="-1">黑暗时代中的魔法 <a class="header-anchor" href="#黑暗时代中的魔法" aria-label="Permalink to &quot;黑暗时代中的魔法&quot;">​</a></h3><ul><li><strong>鹰族率先掌握</strong>：新五族中鹰族成为第一批掌握魔法的种族，将其作为巩固统治、压制普通生灵的核心手段</li><li><strong>法师阶级形成</strong>：法师数量逐渐增多，形成了法师阶级，逐渐改变了共同体的权力结构</li><li><strong>自立城邦</strong>：许多法师不会选择在共同体的体制内生活，而是去到偏远地区自立城邦统治普通人</li><li><strong>天赋筛查</strong>：黑暗时代上层系统性筛查4-8岁的新生奴隶（魔法觉醒核心期），发现天赋者即刻处死</li></ul><h2 id="黑暗时代后的法师体系" tabindex="-1">黑暗时代后的法师体系 <a class="header-anchor" href="#黑暗时代后的法师体系" aria-label="Permalink to &quot;黑暗时代后的法师体系&quot;">​</a></h2><h3 id="黑暗时代后的法师现状" tabindex="-1">黑暗时代后的法师现状 <a class="header-anchor" href="#黑暗时代后的法师现状" aria-label="Permalink to &quot;黑暗时代后的法师现状&quot;">​</a></h3><p>黑暗时代结束后，法师并未消失，仍旧有新生法师出现。然而，由于&quot;法师食人&quot;这一核心秘密的失传（或被刻意隐藏），绝大多数地区的法师力量被严重限制。</p><ul><li><strong>普遍情况</strong>：除鹿国外，大陆其他国家的法师力量十分有限。他们的法师大多只能维持在相当于鹿国&quot;橙章&quot;或以下的水平，即无需食用智慧生物血肉也能存活的强度</li><li><strong>强度上限</strong>：任何法师一旦力量超过某个阈值，便会触发&quot;法师疾病&quot;，因无法摄入智慧生物的血肉而陷入疯狂并迅速死亡。这使得外部法师几乎不可能诞生强大的个体</li><li><strong>例外情况</strong>：少数外部强大法师的存在，通常源于两种途径： <ol><li><strong>秘密食人</strong>：暗中进行禁忌的食人行为以维持生命</li><li><strong>使用鹿国特制药剂</strong>：通过黑市、劫掠等渠道获取鹿国制造的抑制类药物（其实就是血液），勉强续命，但其力量和稳定性仍远逊于鹿国正规法师</li></ol></li></ul><h3 id="鹿国法师体系" tabindex="-1">鹿国法师体系 <a class="header-anchor" href="#鹿国法师体系" aria-label="Permalink to &quot;鹿国法师体系&quot;">​</a></h3><p>鹿国是目前已知唯一拥有系统化、成建制强大法师力量的政权。其核心优势在于：<strong>鹿族是唯一知晓&quot;法师食人&quot;真相并拥有解决方案的种族。</strong></p><ul><li><strong>核心秘密</strong>：鹿国高层完整保留了黑暗时代的记录，明确知晓法师疾病的根源与&quot;食用智慧生物血肉&quot;这一缓解手段，能够针对性地培养和管理高阶法师</li><li><strong>战略定位</strong>：鹿国的法师力量并非摆在明面上的常规军队，而是一种<strong>迫不得已的战略储备</strong>，用于应对特定威胁（主要针对熊国的庞大军力）。法师数量稀少，被作为高精尖的精英小队使用</li></ul><h3 id="鹿国法师等级体系" tabindex="-1">鹿国法师等级体系 <a class="header-anchor" href="#鹿国法师等级体系" aria-label="Permalink to &quot;鹿国法师等级体系&quot;">​</a></h3><p>鹿国的法师根据实力、危险程度及所需&quot;供养&quot;等级，被严格划分为不同层级，并通过肩章、服饰等标识进行区分：</p><table tabindex="0"><thead><tr><th style="text-align:left;">等级</th><th style="text-align:left;">标识</th><th style="text-align:left;">特征与能力</th><th style="text-align:left;">供养需求</th><th style="text-align:left;">状态与管理</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>蓝章</strong></td><td style="text-align:left;">蓝色肩章</td><td style="text-align:left;">社区服务级，战斗力较低，主要用于处理小型魔法事务</td><td style="text-align:left;"><strong>无需</strong>血液供养</td><td style="text-align:left;">数量较多，相对安全。</td></tr><tr><td style="text-align:left;"><strong>橙章</strong></td><td style="text-align:left;">橙色肩章 + 披风</td><td style="text-align:left;">正规战士级巅峰，可以上战场了，拥有一定的正面战斗力。披风用于遮掩背后的小型稳定设备</td><td style="text-align:left;"><strong>无需</strong>血液供养</td><td style="text-align:left;">数量较多，可作为常规战力。</td></tr><tr><td style="text-align:left;"><strong>红章</strong></td><td style="text-align:left;">红色肩章 + 半身斗篷</td><td style="text-align:left;"><strong>军团级</strong>，真正的战略力量。实力发生质变。斗篷用于遮掩覆盖胸腹的大型维生设备</td><td style="text-align:left;"><strong>需要</strong>血液供养</td><td style="text-align:left;">数量稀少，被严格管控。晋升红章是危险的分水岭。</td></tr><tr><td style="text-align:left;"><strong>黑章（法神）</strong></td><td style="text-align:left;">黑色袖章</td><td style="text-align:left;"><strong>仅有两名</strong>，实力极度强大，但精神状态极不稳定，接近疯狂</td><td style="text-align:left;">极度依赖血液与精神链接</td><td style="text-align:left;">身后跟随由低阶法师（多为自愿的蓝/橙章）组成的&quot;僧侣团&quot;，通过精神链接装置为其稳定神志。</td></tr><tr><td style="text-align:left;"><strong>僧侣（耗材）</strong></td><td style="text-align:left;">纯色长袍（无章）</td><td style="text-align:left;">并非正式法师等级。多为不愿或无法晋升红章的蓝/橙章法师，或犯了过错的法师</td><td style="text-align:left;">作为&quot;耗材&quot;，燃烧自身精神力</td><td style="text-align:left;">通过精神链接设备为黑章法神提供神志稳定，自身会逐渐消耗殆尽。</td></tr></tbody></table><h3 id="法师辅助设备与技术来源" tabindex="-1">法师辅助设备与技术来源 <a class="header-anchor" href="#法师辅助设备与技术来源" aria-label="Permalink to &quot;法师辅助设备与技术来源&quot;">​</a></h3><ul><li><strong>稳定设备</strong>：橙章以上法师背后佩戴的设备，用于维持身体稳定、抑制法师疾病、保持神志清醒。随着等级提升，设备规模与复杂程度递增，需用披风或斗篷遮掩。其技术来源为<strong>梯形神殿遗留技术</strong>与<strong>鹿族自主研发电子技术</strong>的结合</li><li><strong>精神链接装置</strong>：用于连接黑章法神与&quot;僧侣团&quot;的复杂设备，可将多位法师的精神力汇入法神意识，帮助其维持稳定。这是鹿族在精神控制技术领域的延伸应用</li></ul><h3 id="血液供养体系" tabindex="-1">血液供养体系 <a class="header-anchor" href="#血液供养体系" aria-label="Permalink to &quot;血液供养体系&quot;">​</a></h3><ul><li><strong>渠道</strong>：红章以上法师所需的血液，来源于<strong>正常的国家血库体系</strong>，并非通过圈养智慧种族获得。这构成了鹿国法师体系的<strong>隐藏软肋</strong>——血库供应链一旦被渗透或切断，高阶法师将面临失控风险</li><li><strong>效率</strong>：血液供养的效果劣于直接食用新鲜血肉。红章法师需要更大量的血液或更高频率的补给才能维持状态。这迫使鹿国必须在&quot;法师战力&quot;与&quot;道德/后勤压力&quot;之间做出权衡</li><li><strong>管理</strong>：晋升红章意味着承担&quot;原罪&quot;。法师本人、管理者乃至整个体系都背负着沉重的道德与责任负担</li></ul><h3 id="两名黑章法神" tabindex="-1">两名黑章法神 <a class="header-anchor" href="#两名黑章法神" aria-label="Permalink to &quot;两名黑章法神&quot;">​</a></h3><p><strong>法神·A（状态相对稳定）：</strong></p><ul><li>身后&quot;僧侣团&quot;规模较小（2-4人）</li><li>精神状态尚可维持，能够进行理性交流与战术指挥</li><li>更多作为鹿国法师体系的最高威慑与顾问存在</li></ul><p><strong>法神·B（秃毛黑皮鹿）：</strong></p><ul><li><strong>特征</strong>：全身毛发脱落，皮肤呈深黑色，形似传说中的阿努比斯（但为鹿首）。身体严重畸形，仅靠自身法力和血液勉强维持形态</li><li><strong>精神状态</strong>：已<strong>半疯</strong>，执念极深。身后跟随一队&quot;僧侣&quot;为其稳定神志</li><li><strong>传奇经历</strong>：<strong>从黑暗时代存活至今的老兵</strong>，是鹿族崛起时期的活化石，参与过无数战斗。其存在本身就是鹿国法师力量的象征与底牌</li><li><strong>现状</strong>：长期处于病态，靠强大的意志力和执念吊着一口气。他的身体畸变是<strong>长期、极度滥用魔法并处于病态的结果</strong>，并非单纯因为食人，而是与地脉、变化神权溢散的深层共鸣有关</li></ul><h3 id="法师秘密的知情范围" tabindex="-1">法师秘密的知情范围 <a class="header-anchor" href="#法师秘密的知情范围" aria-label="Permalink to &quot;法师秘密的知情范围&quot;">​</a></h3><ul><li><strong>鹿族</strong>：高层与核心科研团队知晓全部真相（食人、血液供养、疾病原理）</li><li><strong>熊族及其他种族</strong>：<strong>基本不知情</strong>。即使有零星的传言或个别知情人，也因缺乏证据和系统性解决方案而无法形成有效力量</li><li><strong>神明（维斯塔、神机）</strong>：完全知情</li></ul><hr><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><p><a href="./../../叙事与伏笔/伏笔洋葱层分类">伏笔洋葱层分类</a></p></li><li><p><a href="./../../底层/规则/基底层与现实世界" class="layer-link" data-layer="底层">基底层与现实世界</a></p></li><li><p><a href="./../../底层/规则/神权体系" class="layer-link" data-layer="底层">神权体系</a></p></li><li><p><a href="./../历史/前传超算纪元">前传超算纪元</a></p></li><li><p><a href="./../../表层/种族/鹿族" class="layer-link" data-layer="表层">鹿族</a></p></li><li><p><a href="./../人物/维斯塔">维斯塔</a></p></li><li><p><a href="./../人物/神机">神机</a></p></li></ul><hr>',67)])])}const f=l(n,[["render",s]]);export{q as __pageData,f as default};
